import assert from "node:assert/strict";
import { test } from "node:test";
import { FOOTER_PATTERN } from "./notes-contract.ts";

test("the footer pattern accepts the provenance line and refuses near misses", () => {
  const footer =
    "> Generated by [Agentics release](https://github.com/muehz/agentics/actions/runs/5001) · claude · opus";
  assert.match(footer, FOOTER_PATTERN);
  for (const bad of [
    footer.replace(" · ", " - "),
    footer.replace("Agentics release", "Other"),
    `${footer} · extra`,
    `${footer}\nsecond line`,
    footer.replace("> ", ""),
    footer.replace("/runs/5001", "/runs/0"),
  ]) {
    assert.doesNotMatch(bad, FOOTER_PATTERN, bad);
  }
});
